import { PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

function hexRGB(value, fallback) {
  if (typeof value !== 'string') return fallback;
  const hex = value.replace('#', '');
  if (hex.length !== 6) return fallback;
  const n = Number.parseInt(hex, 16);
  if (!Number.isFinite(n)) return fallback;
  return [
    ((n >> 16) & 255) / 255,
    ((n >> 8) & 255) / 255,
    (n & 255) / 255,
  ];
}

function makeGradientMaterial(stops) {
  const material = new MeshBasicNodeMaterial();
  const colors = stops.map((stop) => vec3(...hexRGB(stop, [0.043, 0.043, 0.063])));
  const y = uv().y;

  if (colors.length === 1) {
    material.colorNode = colors[0];
    return material;
  }

  if (colors.length === 2) {
    material.colorNode = mix(colors[0], colors[1], smoothstep(0.05, 0.95, y));
    return material;
  }

  const midpoint = smoothstep(0.38, 0.62, y);
  const lower = mix(colors[0], colors[1], smoothstep(0.0, 0.62, y));
  const upper = mix(colors[1], colors[2], smoothstep(0.38, 1.0, y));
  material.colorNode = mix(lower, upper, midpoint);
  return material;
}

export default function createNode(config, ctx) {
  const group = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const colors =
    config.intent?.visualSpec?.colors ??
    config.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10',
    };

  const visualSpec = config.intent?.visualSpec ?? {};
  const gradientStops =
    visualSpec.gradientStops ??
    [colors.surface, colors.ink, colors.primary ?? colors.ink];

  const backdropMaterial = makeGradientMaterial(gradientStops);
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.position.set(3.2, 0.3, -2.5);
  group.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.52,
    depthWrite: false,
  });
  const shadow = new Mesh(new PlaneGeometry(3.35, 0.42), shadowMaterial);
  shadow.position.set(0, -1.12, -0.08);
  shadow.scale.set(1, 0.55, 1);
  group.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
  });
  const imagePlane = new Mesh(new PlaneGeometry(2.7, 1.69), imageMaterial);
  imagePlane.position.set(0, 0.08, 0);
  group.add(imagePlane);
  resources.push(imagePlane.geometry, imagePlane.material);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
  });
  const frame = new Mesh(new PlaneGeometry(2.86, 1.85), frameMaterial);
  frame.position.set(0, 0.08, -0.025);
  group.add(frame);
  resources.push(frame.geometry, frame.material);

  group.remove(imagePlane);
  group.add(imagePlane);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
  });

  const accentTop = new Mesh(new PlaneGeometry(0.62, 0.035), accentMaterial);
  accentTop.position.set(-0.92, 1.045, 0.045);
  group.add(accentTop);
  resources.push(accentTop.geometry);

  const accentSide = new Mesh(new PlaneGeometry(0.035, 0.42), accentMaterial);
  accentSide.position.set(1.42, -0.61, 0.045);
  group.add(accentSide);
  resources.push(accentSide.geometry);
  resources.push(accentMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed) {
        loadedTexture.dispose?.();
        return;
      }
      loadedTexture.colorSpace = 'srgb';
      imageMaterial.colorNode = texture(loadedTexture, uv());
      imageMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    group.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power3.out' },
  );
  entrance.fromTo(
    group.position,
    { y: -0.18 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0,
  );
  entrance.play();
  timelines.push(entrance);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    group.clear();
  };

  return group;
}
